// Disposable browser-verification stack: in-memory MongoDB + seeded catalog + API on :5000.
// Never point this at the hosted cluster — the URI is generated by mongodb-memory-server.
// Run with: node scripts/dev-stack.mjs
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import dotenv from 'dotenv';
import mongoose from 'mongoose';
import memory from 'mongodb-memory-server';
import session from 'express-session';
import { useTestEnv } from '../tests/helpers/env.js';

// Loaded by path so the stack behaves the same whether it is started from
// backend/ or from the frontend test runner.
dotenv.config({ path: path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '.env') });

const PORT = Number(process.env.CFT_DEV_STACK_PORT || 5000);
const FRONTEND = process.env.CFT_DEV_STACK_FRONTEND || 'http://127.0.0.1:5180';
export const funnelUser = {
  student: { email: 'browser.student@verify.test', password: 'BrowserVerify2026' },
  admin: { email: 'browser.admin@verify.test', password: 'BrowserAdmin2026' }
};

export async function startDevStack({ quiet = false, useRealAuth = false, liveMail = false } = {}) {
  const mongo = await memory.MongoMemoryReplSet.create({ replSet: { count: 1, storageEngine: 'wiredTiger' } });

  // A person clicking through the site expects whatever backend/.env switches on:
  // real Google sign-in and real Bunny tokens, so the lessons actually play.
  // The automated suite keeps the deterministic fake values instead.
  const realFromEnv = useRealAuth
    ? {
        ...(process.env.GOOGLE_CLIENT_SIGNIN_KEY
          ? {
              AUTH_GOOGLE_ENABLED: process.env.AUTH_GOOGLE_ENABLED || 'true',
              GOOGLE_CLIENT_ID: process.env.GOOGLE_CLIENT_ID,
              GOOGLE_CLIENT_SIGNIN_KEY: process.env.GOOGLE_CLIENT_SIGNIN_KEY
            }
          : {}),
        ...(process.env.BUNNY_SIGNING_KEY
          ? {
              BUNNY_API_KEY: process.env.BUNNY_API_KEY,
              BUNNY_LIBRARY_ID: process.env.BUNNY_LIBRARY_ID,
              BUNNY_SIGNING_KEY: process.env.BUNNY_SIGNING_KEY
            }
          : {})
      }
    : {};

  useTestEnv({
    PORT: String(PORT),
    MONGODB_URI: mongo.getUri('cft_browser'),
    FRONTEND_URL: FRONTEND,
    BACKEND_URL: `http://127.0.0.1:${PORT}`,
    CORS_ALLOWED_ORIGINS: FRONTEND,
    AUTH_OTP_EMAIL_ENABLED: 'true',
    AUTH_MAGIC_LINK_ENABLED: 'true',
    VIDEO_MAX_CONCURRENT_SESSIONS: '1',
    // Only a manual run uses backend/.env mail. The automated stacks keep the
    // mock provider so the codes and links they read from stdout still appear,
    // and so no test address ever costs a real Resend request.
    EMAIL_PROVIDER: liveMail ? process.env.EMAIL_PROVIDER : 'mock',
    RESEND_API_KEY: liveMail ? process.env.RESEND_API_KEY || undefined : undefined,
    EMAIL_FROM: liveMail ? process.env.EMAIL_FROM || undefined : undefined,
    ADMIN_NOTIFY_EMAIL: liveMail ? process.env.ADMIN_NOTIFY_EMAIL || undefined : undefined,
    ...realFromEnv
  });

  await mongoose.connect(process.env.MONGODB_URI);
  await Promise.all(Object.values(mongoose.models).map((model) => model.init()));

  const { seedCatalog } = await import('./seed.js');
  await seedCatalog();

  const { User } = await import('../src/models/index.js');
  for (const [role, account] of Object.entries(funnelUser)) {
    const existing = await User.findOne({ email: account.email });
    if (existing) continue;
    const user = new User({
      name: role === 'admin' ? 'Browser Admin' : 'Browser Verify',
      email: account.email,
      role,
      emailVerified: true,
      status: 'active'
    });
    await user.save();
    await user.setPassword(account.password);
  }

  const { createApp } = await import('../src/app.js');
  const app = createApp({ sessionStore: new session.MemoryStore() });
  const server = await new Promise((resolve, reject) => {
    const listening = app.listen(PORT, '127.0.0.1', () => resolve(listening));
    listening.once('error', reject);
  });

  if (!quiet) {
    console.log(`dev-stack ready on http://127.0.0.1:${PORT} (mock payments, seeded catalog, in-memory db)`);
    console.log(`student ${funnelUser.student.email} / ${funnelUser.student.password}`);
    const mailLive = liveMail && process.env.EMAIL_PROVIDER === 'resend' && !!process.env.RESEND_API_KEY;
    console.log(mailLive
      ? `Mail is live through Resend from ${process.env.EMAIL_FROM}. Until that sender domain is verified, Resend only delivers to the account owner's own address.`
      : 'No mailbox is connected in this stack: email codes print here as [otp:dev] and sign-in links as [magic:dev].');
    const googleLive = process.env.AUTH_GOOGLE_ENABLED === 'true' && process.env.GOOGLE_CLIENT_ID;
    console.log(googleLive
      ? `Google sign-in on with client ${process.env.GOOGLE_CLIENT_ID}, that origin must be an authorized JavaScript origin in Google Console.`
      : 'Google sign-in off (no client secret in backend/.env).');
    console.log(process.env.BUNNY_SIGNING_KEY
      ? `Bunny embed tokens signed for library ${process.env.BUNNY_LIBRARY_ID}, lessons play with a time-limited URL.`
      : 'Bunny signing key missing in backend/.env, every lesson will come back as 403 Forbidden.');
  }

  const stop = async () => {
    await new Promise((resolve) => server.close(resolve));
    await mongoose.disconnect();
    await mongo.stop();
  };

  return { server, mongo, stop, apiOrigin: `http://127.0.0.1:${PORT}` };
}

// Compares resolved URLs so a Windows backslash argv still counts as "run directly".
const startedDirectly = Boolean(process.argv[1]) && pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url;
if (startedDirectly) {
  const stack = await startDevStack({ useRealAuth: true, liveMail: true });

  // Only when a human is driving the site by hand: the mock provider still never
  // marks an order paid on its own, so this stands in for the provider's webhook
  // after a short pause. The automated funnel leaves it off and confirms manually.
  if (process.env.CFT_DEV_AUTO_PAY !== '0') {
    const { paymentEvent, deliver } = await import('../tests/helpers/payment-simulator.js');
    const { Order } = await import('../src/models/index.js');
    const timer = setInterval(async () => {
      try {
        const stale = await Order.find({ paymentStatus: 'pending', updatedAt: { $lt: new Date(Date.now() - 2500) } }).select('_id');
        for (const order of stale) await deliver(paymentEvent(String(order._id)));
      } catch { /* the stack is coming down */ }
    }, 1500);
    timer.unref();
    console.log('auto-pay is ON: a pending mock order is confirmed by the simulated provider after a few seconds.');
  }

  for (const signal of ['SIGINT', 'SIGTERM']) process.on(signal, () => stack.stop().then(() => process.exit(0)));
}
